/* SMS business specifications. Inputs are published ledgers and offline evidence. */
const fs=require('node:fs'),path=require('node:path');
const registry=require('./sms-published-registry.json');
const S='/back/schedule/common',D='/back/schedule/dtm',G='/back/gldm/base',E='/back/schedule/general';
const table=(h,rows)=>['| '+h.join(' | ')+' |','|'+h.map(()=>'---').join('|')+'|',...rows.map(r=>'| '+r.map(x=>String(x??'').replaceAll('|','&#124;').replaceAll('\n','<br>')).join(' | ')+' |'),''];
const f=(n,t,required='',def='',limit='',rule='',error='',state='')=>[n,t,required,def,limit,rule,error,state];
const ro=(n,t='只读文本',rule='')=>f(n,t,'','','',rule,'','结果展示');
const query=(n,key)=>f(n+' '+key,'可清空文本','否','','','trim首尾空白；查询时提交，不在输入每个字符时发请求','','筛选');
const page=[f('分页 pageRequest.pageNo','integer','是','1','正整数','查询与重置回第1页'),f('每页条数 pageRequest.pageSize','integer','是','20','正整数','改变条数回第1页；不是数据总量上限'),f('排序 pageRequest.order','array<object>','是','[{prop:"id",asc:false}]','','服务端允许字段按契约；客户端局部排序不等于全量排序')];
const api=(purpose,method,url,params,result='普通resolve按公共客户端处理；列表读取datas/total，字段格式见字段表')=>[purpose,method,url,params,result];
const splitLayout='顶端全局导航、左侧模块导航，正文标题下为筛选白卡，查询/重置在右；下一白卡的操作区在表格上方，蓝色表头、空态居中，分页位于底部靠右。宽列在卡片内横向滚动，不能遮挡操作。';
const formLayout='顶端页头标题和右侧返回；表单白卡按标签在上、输入在下对齐，必填标记与字段关联；底部取消/提交固定在正文操作栏，长表单在内容区滚动。';
function list(route,goal,fields,requests,controls,sources,flow=[],layout=splitLayout){return {route,goal,fields:[...fields,...page],requests,controls:[['筛选/查询/Enter','输入仅改草稿，查询与Enter使用同一入口并回第1页；清空保留0/false有效值。'],['重置','清除本页筛选并恢复本功能定义的初始状态，回第1页读取。'],['分页/每页条数','按已提交条件读取目标页，修改条数回1页；禁止迟到响应覆盖新筛选。'],...controls],sources,flow,layout,write:false};}
function edit(route,goal,fields,requests,controls,sources,flow=[],layout=formLayout){return{route,goal,fields,requests,controls:[...controls,['提交','先逐字段及组合校验，失败定位错误；提交中锁住重复入口，成功按真实回执回读，不由提示推断外部执行。'],['取消/返回/后退','未保存变化需确认后丢弃当前草稿并回来源页；已发生的上传或初始化不得宣称回滚。']],sources,flow,layout,write:true};}
const P={};
P.home={route:'/sms/home',goal:'查看当前身份范围内今日执行总数、成功数、失败数及小时趋势。',fields:[ro('欢迎名称 companyName','文本','从父应用userInfo.name读取，不作权限来源'),...['totalCount','successCount','failCount'].map(x=>f(x,'计数 number','',0,'','0是组件初始值；读取成功后才作为业务计数','','统计卡')),ro('totalTrend / successTrend / failTrend','array<{name,num}>','按name小时对齐；横轴name+:00；缺系列不能补造成功计数')],requests:[api('今日统计','GET',S+'/stat/statDataToday','无业务查询体','totalCount/successCount/failCount及三组Trend')],controls:[['进入/重试','读取当日统计；区分加载、无数据、失败，不能把初始化0显示为查询成功。'],['图表悬停/缩放','显示小时、系列及数量；resize适配容器，离页清除监听。']],sources:['HOME','HOME-API'],flow:['读取成功一次性更新三卡与三系列；失败保留最后成功数据并标明时间/失败。','本页是统计概览，无新增、删除或分页控件；全局导航进入流程开发/调度时保留模块路由语义。'],layout:'标题下欢迎区，今日三项计数横排；下方小时趋势图独立卡片。图例、颜色与文字同时区分系列；窄屏按卡片换行。',write:false};
P.flow={route:'/sms/develop/taskDevelop',goal:'按流程树组织并定位定义，以稳定flowId进入画布，区分定义保存、发布和执行。',fields:[f('树过滤 filterText','文本','否','空字符串','','只过滤名称，不改流程/分组'),ro('流程组/流程节点 id、name、children','树节点','分组与流程节点类型分开，树节点id不能直接当执行实例id'),ro('当前流程 flowId / 状态 taskStatus','ID/number','随树选择读取，不以高亮文字作为ID'),f('名称 name','文本','维护时必填','','','新增/改名规则以所属弹窗和服务端契约约束；不据树样本定义全局唯一性'),ro('画布节点/边 nodes、edges','图数据','完整节点协议及版本受交付契约约束，不能仅凭导航生成可运行任务')],requests:[api('加载流程树','POST',S+'/flowcategory/data','无业务体','流程分组和定义树'),api('读取流程定义','GET',S+'/flowdefinition/{id}','path id来自选中流程','定义及版本/节点数据，按交付契约'),api('分组/定义维护','POST / PUT / DELETE',S+'/{flowcategory|flowdefinition}[/{id}]','POST新增、PUT编辑、DELETE删除；仅人工动作；对象类型与ID必须匹配'),api('保存/发布/撤销发布','PUT',S+'/flowdefinition/{save|deploy|undeploy}/{id}','save带当前图草稿；deploy/undeploy由人工分别确认','保存成功不等于发布/执行成功')],controls:[['树筛选/展开/双击','过滤或展开不发写请求；双击流程打开对应flowId，分组不可当流程运行。'],['新建流程组/流程/改名/移动/删除','先选正确父组及动作权限，编辑对话框确认后才提交；引用/运行态/跨组权限冲突保留上下文。'],['保存/发布/试运行/导入导出','分别授权；离开未保存图需确认；试运行和导入有副作用，不因取证自动调用。']],sources:['FLOW','DEVELOP-API'],flow:['进入读取树→选择定义→加载画布；空树给创建引导，树错误给重试。','画布校验需包含节点必填、引用归属、孤立/闭环及版本冲突；后端节点/连线协议、循环例外、停止与重跑范围交付前仅开放相应前端草稿开发。'],layout:'左侧流程树及搜索/新建入口，右侧流程编辑主区与工具栏；无选择时显示双击进入画布的指引。复杂画布不套列表分页。',write:true};
P.schedule=list('/sms/schedule/manage/scheduleList','查询已发布流程的调度配置，按所选定义单次执行、启动或停止，逐项核对结果。',[query('流程名称','obscureName'),ro('流程 id','稳定ID','配置与批量操作使用定义id'),...['name','statusUsername','statusTime'].map(x=>ro(x)),ro('流程状态 status','number','1开发、2发布、3已配置、4运行、5暂停、6停止；非实例状态机'),ro('调度策略 strategy','number','1定时、2事件、3单次'),f('选中行 multipleSelection','array<row>','否','[]','','提交选中行id，不以当前页索引代替')],[api('查询','POST',S+'/flowdefinition/page','body {obscureName?,pageRequest}'),api('单次/启动/停止','PUT',S+'/flowdefinition/{execs|starts|stops}','body array<ID>；execs单次、starts启动、stops停止','返回数组逐项读取id/code/msg；code===0成功，其他失败'),api('策略保存','PUT',S+'/flowdefinition/strategy/{id}','path定义id；body策略草稿，见本节策略字段'),api('批量策略保存','PUT',S+'/flowdefinition/strategys','body策略草稿+ids数组')],[['行DAG','进入/develop/flowCanvas，query id、optType=view、name；只读图不能触发运行。'],['调度配置','单项进入/schedule/manage/scheduleSetting?id={id}&cronExp={值}；批量ids为逗号连接；无选中只提示、不请求。批量包含status=4先停止再配。'],['单次运行/流程启动/流程停止','动作分别验权；选中后人工发起，返回逐项显示成功/失败及msg，保留失败ID；不能用HTTP成功替代全部成功。'],['最近运行计划','仅strategy=1；Cron预览显示未来5次，不代表调度器已承诺计划；时区及Cron语义见公共规则。']],['SCHEDULE','SETTING','SCHEDULE-API'],['定义、计划、实例为三个对象。调度配置不新建独立流程；删除定义回流程开发，不能为调度列表凭空增加删除计划接口。','保存并运行先保存策略，再按strategy=3调用execs，其余调用starts；第二步失败时显示“策略已保存、运行失败”，先查运行结果，再允许人工补启动；无已证实跨请求回滚。']);
P.periodic=list('/sms/schedule/monitor/monitorList','监控周期执行实例，按状态过滤并查看任务日志或停止实例。',[query('流程名称','obscureName'),f('实例筛选 statusList','radio→array<number>','是','[1]','1、0、7、5|6|61','运行、等待、成功、异常；字符串按|拆分Number；重置保留当前状态'),ro('实例 id / flowName / status','ID/文本/number','id为实例id；完整状态枚举见公共规则'),ro('startTime / endTime','日期时间'),ro('运行时长','秒','两端齐全才(end−start)/1000；否则显示-')],[api('实例分页','POST',S+'/flowinstance/page','body {obscureName?,statusList,pageRequest}'),api('停止实例','PUT',S+'/flowinstance/stop/{id}','path实例id，人工确认','请求受理不等于已停止；按实例回读'),api('实例节点及日志','POST',S+'/taskinstance/list','body实例关联条件按日志页契约','日志路由/schedule/monitor/logList?id={实例id}')],[['状态单选','按1运行/0等待/7成功/5|6|61异常重新查询；不能用定义status=6停止套入实例6失败。'],['重置特例','只清obscureName，保留当前statusList，回第1页。'],['日志/停止','日志携带实例id；停止仅当前允许状态可用，服务器重核实例归属及并发状态。']],['PERIODIC','PERIODIC-API'],['进入默认[1]；有任务等待/执行/终态分别展示。停止超时进入结果未知，先回读实例再决定是否重试。','监控历史截图正文错时；列头与行为以周期组件定义为依据，不把调度管理截图当监控布局验收。']);
P.realtime=list('/sms/schedule/monitor/realtime','按流程、状态及开始时间监控实时作业，独立启停及查看实时日志。',[query('流程名称','flowName'),f('状态 status','可清空单选 number','否','','1、5、6、7','1运行、5未启动、6失败、7结束'),f('开始时间 timeArr','日期时间范围','否','[]','','映射beginStartTime/endStartTime；清空两者空字符串；禁止未来日期'),ro('实时作业 id / flowName / status / startTime','结果字段','不能以告警id或周期实例id替换')],[api('查询','POST',S+'/flowRealTime/page','body {flowName?,status?,beginStartTime,endStartTime,pageRequest}'),api('单项启停','PUT',S+'/flowRealTime/{start|stop}/{id}','path当前实时行id'),api('批量启停','PUT',S+'/flowRealTime/{starts|stops}','body array<ID>','逐项code===0成功，其余失败'),api('日志列表','POST',S+'/flowRealTime/logList/{id}','path实时行id；body分页/过滤参数以日志组件契约','进入日志路由query id,type=realtime')],[['时间/状态','清空不残留旧范围；0/空值不擅自映射为运行。'],['单项或批量启停','无选中阻止；启停分别验权、运行冲突回读，不能只切本地状态。'],['查看日志','传当前行id和type=realtime，保持实时与周期查询链路分离。']],['REALTIME','REALTIME-API'],['批量结果保留成功与失败子集，未知结果先核查；重试仅限核清的失败项，不能重放已成功启动项。']);
P.alarm=list('/sms/schedule/alarm/messageList','查找告警并以处理原因和处理状态形成可追溯的处置记录。',[query('流程名称','flowDefinitionName'),f('告警时间 alarmTime','日期时间范围','否','[]','','映射alarmTimeStart/End；清空两者空字符串，禁止未来日期'),f('推送条件 alarmPush','筛选选择','否','','','按告警页面候选值提交，不自定义枚举'),ro('告警 id / flowInstanceId / flowDefinitionName / alarmTime','结果字段','告警id用于处置，flowInstanceId用于日志'),f('处理状态 handleStatus','单选 number','是','2','1、2、3、4','已处理、未处理、挂起、暂时规避；仅未处理2可进入修改'),f('处理原因 handleCause','textarea','处置时必填','空字符串','500字符','trim后非空，不能仅空格'),f('处置 ids','array<ID>','是','','','来自未处理告警选择项')],[api('查询','POST',S+'/workalarm/page','body {flowDefinitionName?,alarmTimeStart?,alarmTimeEnd?,alarmPush?,pageRequest}'),api('处置','PUT',S+'/workalarm/handle','body {ids,handleCause,handleStatus}','持久处置回读；并发已处理时拒绝覆盖')],[['选中/处理','仅handleStatus=2可选处置；其他状态进入只读详情，不绕过禁选。'],['处理原因/状态/提交','600px处置弹窗内输入原因、选择合法后继状态；后继状态迁移由后端契约约束，不默认任意互转。'],['查看日志','以flowInstanceId进入日志页，pageFrom=alarm；传流程/节点/时间上下文，不把告警id当实例id。']],['ALARM','ALARM-API'],['处置前读取最新状态，确认后提交；失败保留原因草稿与选择；超时先按ids核处置结果。']);
P.push=list('/sms/schedule/alarm/pushList','维护告警接收对象、频率、监控范围及状态。',[query('接收人','obscureName'),ro('id / receiver / frequency / type / status','推送配置','候选和映射见新增规格；保存不证明邮件送达')],[api('分页','POST',S+'/mailInfo/page','body筛选及pageRequest'),api('详情/编辑/删除','GET / PUT / DELETE',S+'/mailInfo/{id}','path配置id；PUT为表单；DELETE需人工确认','读取/维护配置，不替代外部通知回执')],[['新增','进入/schedule/alarm/pushEdit?optType=add。'],['查看/编辑','读取当前配置id；只读时所有字段禁改、无提交。'],['删除','确认对象/作用范围；服务端拒绝引用或越权，结果未知先查配置，不能重复删除错误对象。']],['PUSH','PUSH-API'],['列表和配置回读不触发测试邮件；频率按小时/天的窗口与去重由通知契约定义。']);
